打开(创建)文件

pub fn sysopen(path: const u8, flags: u32) - isize {
    //调用openfile函数获得一个OSInode结构的inode
    if let Some(inode) = openfile(path.asstr(), 
                           OpenFlags::frombits(flags).unwrap()) {
        let mut inner = task.innerexclusiveaccess();
        let fd = inner.allocfd();  //得到一个空闲的fdtable项的idx，即fd
        inner.fdtable[fd] = Some(inode); //把inode填入fdtable[fd]中
        fd as isize  //返回fd 
    ...
