基于文件加载应用（ELF可执行文件格式）
    pub fn sysexec(path: const u8) - isize {
        if let Some(appinode) = openfile(path.asstr(), ...) {
            let alldata = appinode.readall();
            let task = currenttask().unwrap();
            task.exec(alldata.asslice()); 0
    } else { -1 }

